#!/bin/sh

# Reject direct pushes to main/develop (they only change through a merged PR)
# and to server (generated by .github/workflows/server-branch.yml), then run every check
# when a branch is pushed.
# Exception: main can be pushed to the gitlab mirror after a promotion.
# Tag pushes, the gitlab mirror and branch deletions run no check: scripts/release.sh pushes
# the tag and the mirror after the irreversible merge, a failing check there would stop it
# half done.
# SKIP_CHECKS=1 skips only the checks (intermediate pushes); the branch guard always runs.
# --no-verify skips the whole hook, guard included: GitHub branch protection still refuses
# direct pushes to main and develop.
# Install: cp .githooks/pre-push.sh .git/hooks/pre-push && chmod +x .git/hooks/pre-push

remote="$1"
protected="main develop server"
zero_sha="0000000000000000000000000000000000000000"
run_checks=false

while read -r _local_ref local_sha remote_ref _remote_sha; do
    case "$remote_ref" in
        refs/heads/*) ;;
        *) continue ;;
    esac
    branch=${remote_ref#refs/heads/}
    if [ "$remote" = "gitlab" ] && [ "$branch" = "main" ]; then
        continue
    fi
    for p in $protected; do
        if [ "$branch" = "$p" ]; then
            echo "✖ Direct push to '$p' on '$remote' is forbidden."
            echo "  Use a <type>/* branch + a Pull Request."
            exit 1
        fi
    done
    if [ "$local_sha" != "$zero_sha" ]; then
        run_checks=true
    fi
done

if [ "$run_checks" = false ]; then
    exit 0
fi
if [ "${SKIP_CHECKS:-}" = "1" ]; then
    echo "SKIP_CHECKS=1: checks skipped, the branch guard ran."
    exit 0
fi

# Every test, the Cinnamon checks and shellcheck (scripts/check-all.sh, under a minute).
# git exports GIT_DIR, GIT_INDEX_FILE and friends to hooks (githooks(5)): the tests' own
# `git init` and `git config` would then write into this repository (core.bare=true broke
# the main checkout on 2026-11-16). The hook runs from the work tree root, so plain git
# commands still find the repository without them.
unset GIT_DIR GIT_WORK_TREE GIT_INDEX_FILE GIT_OBJECT_DIRECTORY GIT_COMMON_DIR \
    GIT_ALTERNATE_OBJECT_DIRECTORIES GIT_PREFIX
repo_root="$(git rev-parse --show-toplevel)"
if [ -x "$repo_root/scripts/check-all.sh" ]; then
    if ! "$repo_root/scripts/check-all.sh"; then
        echo "✖ scripts/check-all.sh failed: push cancelled."
        exit 1
    fi
fi

exit 0
